	if !Enable.Get(&s.st.SV) {
		return
	}

	tableStats := s.getStatsForTableID(key.TableID, true /* createIfNotExists */)
	indexStats := tableStats.getStatsForIndexID(key.IndexID, true /* createIfNotExists */)
