func splitColumnDefsAndTableConstraints(body string) (colDefs, tableConstraints []string) {
	// Split the body into parts based on commas, respecting parentheses
	var partsList []string
	buf := ""
	depth := 0
	for _, ch := range body {
		switch ch {
