		// Nothing to show; flags are shown separately.

	case *ExplainPrivate, *opt.ColSet, *types.T, *ExportPrivate:
		// Don't show anything, because it's mostly redundant.

	default:
		if f.RedactableValues {
			redact.Fprintf(f.Buffer, " %v", private)
