func bitmaskOp(aStr, bStr string, op func(byte, byte) byte) (*tree.DBitArray, error) {
	aLen, bLen := len(aStr), len(bStr)
	bufLen := max(aLen, bLen)
	buf := make([]byte, bufLen)
	for i := 0; i < bufLen; i++ {
		var a, b byte

		if i >= aLen {
