			})

		var timer timeutil.Timer
		defer timer.Stop()

		for {
			interval := kvadmission.FlowTokenDropInterval.Get(&t.st.SV)
			if interval > 0 {
				timer.Reset(interval)
			} else {
				// Disable the mechanism.
				timer.Stop()
